#!/usr/bin/env python3
"""Generated by writing-skill-scripts; edit scripts/uv-tools-expose.json instead."""
import os
import sys
from pathlib import Path

ROOT = (Path(__file__).resolve().parent / '..').resolve()
COMMAND = 'use-bcachefs'
SUBCOMMANDS = {'dkms-port-check': 'scripts/dkms-port-check.sh', 'grub-canary-check': 'scripts/grub-canary-check.sh'}
# A helper is run by its own interpreter when it is not directly executable.
INTERPRETERS = {".py": [sys.executable], ".js": ["node"], ".mjs": ["node"]}


def usage(stream=sys.stdout):
    stream.write(f"usage: {COMMAND} <subcommand> [args...]\n\nsubcommands:\n")
    stream.write("".join(f"  {name}\n" for name in sorted(SUBCOMMANDS)))


def main():
    if len(sys.argv) == 1 or sys.argv[1] in {"-h", "--help"}:
        usage()
        return 0
    relative = SUBCOMMANDS.get(sys.argv[1])
    if relative is None:
        print(f"{COMMAND}: unknown subcommand: {sys.argv[1]}", file=sys.stderr)
        usage(sys.stderr)
        return 2
    target = ROOT / relative
    if not target.is_file():
        print(f"{COMMAND}: helper missing: {target}", file=sys.stderr)
        return 2
    interpreter = INTERPRETERS.get(target.suffix)
    if interpreter:
        os.execvp(interpreter[0], [*interpreter, str(target), *sys.argv[2:]])
    os.execv(target, [str(target), *sys.argv[2:]])


if __name__ == "__main__":
    raise SystemExit(main())
